import pty, os, subprocess, select, struct, fcntl, termios, tempfile, time

def run_test(args, stdout_is_pty, stderr_is_pty, stdin_is_pty, stdout_cols=80, stderr_cols=80, stdin_cols=80):
    stdin_data = bytes([i%256 for i in range(500)])
    # we need to handle stdin: if stdin_is_pty, we need to feed via pty? Simpler: use file arg for input, so stdin is not used for data, but for winsize detection, stdin tty still matters? We'll set stdin to pty with given width but no data (just /dev/null? Actually need to keep pty open)
    # For file input, stdin is not used, but terminal_size might check stdin. We'll set stdin fd accordingly.
    with tempfile.NamedTemporaryFile(delete=False) as f:
        f.write(stdin_data)
        fname = f.name
    # stdout
    if stdout_is_pty:
        out_master, out_slave = pty.openpty()
        fcntl.ioctl(out_slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, stdout_cols, 0, 0))
        stdout_fd = out_slave
    else:
        out_r, out_w = os.pipe()
        stdout_fd = out_w
    if stderr_is_pty:
        err_master, err_slave = pty.openpty()
        fcntl.ioctl(err_slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, stderr_cols, 0, 0))
        stderr_fd = err_slave
    else:
