def parse_env_color(s):
    # s is env var value, e.g., "red", "bright blue", "#ff0000"
    # Returns ANSI code string like "\x1b[31m" or "\x1b[38;2;R;G;Bm" or None if invalid (caller falls back to default)
    # Valid: black, red, green, yellow, blue, magenta, cyan, white (lower only) -> 30-37
    # bright <color> (single space, lower) -> 90-97
    # #rrggbb (7 chars, # +6 hex, case-insensitive for hex? Yes #ff0000 and #FF0000 both work, what about mixed? Likely works if all hex digits)
    # All else invalid -> None
    if s in ("black","red","green","yellow","blue","magenta","cyan","white"):
        m = {"black":30,"red":31,"green":32,"yellow":33,"blue":34,"magenta":35,"cyan":36,"white":37}
        return f"\x1b[{m[s]}m"
    if s.startswith("bright "):
        rest = s[7:]
        if rest in ("black","red","green","yellow","blue","magenta","cyan","white"):
            # check exact: s must be "bright <color>" with single space, no extra spaces. Our check: s == "bright "+rest and rest valid and s has no extra? Since we check startswith and rest exact, but what about "bright  black" (double space)? Then rest would be " black" (with leading space), not in list, so invalid -> None. Good. What about "bright black " (trailing)? Then rest="black " (with trailing), not in list -> None. Good. What about " bright black" (leading)? Then s doesn't start with "bright ", so invalid. Good.
            # Also need to ensure s == "bright "+rest exactly (no extra)? Our logic already ensures, since rest is s[7:], and we check rest in list (which has no spaces). So "bright black" passes, "bright black " fails (rest "black " not in list). Good.
            m2 = {"black":90,"red":91,"green":92,"yellow":93,"blue":94,"magenta":95,"cyan":96,"white":97}
            return f"\x1b[{m2[rest]}m"
        else:
            return None
    if len(s)==7 and s[0]=="#" :
        hexpart = s[1:]
        # check 6 hex digits
        for ch in hexpart:
            if ch not in "0123456789abcdefABCDEF":
                return None
        try:
            r = int(hexpart[0:2],16)
            g = int(hexpart[2:4],16)
            b = int(hexpart[4:6],16)
            return f"\x1b[38;2;{r};{g};{b}m"
        except:
            return None
    return None

def get_default_colors():
    # returns dict of category -> ANSI code, considering env overrides (for default scheme)
    # categories: null, printable, whitespace, other, nonascii, offset
    # defaults: null 90, printable 36, whitespace 32, other 32, nonascii 33, offset 90
    defaults = {
        "null": "\x1b[90m",
        "printable": "\x1b[36m",
        "whitespace": "\x1b[32m",
        "other": "\x1b[32m",
        "nonascii": "\x1b[33m",
        "offset": "\x1b[90m",
    }
    env_map = {
        "null": "HEXYL_COLOR_NULL",
        "printable": "HEXYL_COLOR_ASCII_PRINTABLE",
        "whitespace": "HEXYL_COLOR_ASCII_WHITESPACE",
        "other": "HEXYL_COLOR_ASCII_OTHER",
        "nonascii": "HEXYL_COLOR_NONASCII",
        "offset": "HEXYL_COLOR_OFFSET",
    }
    res = {}
    for cat, envvar in env_map.items():
        v = os.environ.get(envvar)
        if v is not None:
            c = parse_env_color(v)
            if c is not None:
                res[cat] = c
            else:
                res[cat] = defaults[cat]
        else:
            res[cat] = defaults[cat]
    return res

def get_offset_color():
    # for gradient scheme, only offset respects env, others use gradient
    v = os.environ.get("HEXYL_COLOR_OFFSET")
    if v is not None:
        c = parse_env_color(v)
        if c is not None:
            return c
    return "\x1b[90m"

