# --- CLI parsing ---
LONG_USAGE_ALL = "<FILE|--length <N>|--skip <N>|--block-size <SIZE>|--no-squeezing|--color <WHEN>|--border <STYLE>|--plain|--no-characters|--characters|--character-table <FORMAT>|--color-scheme <FORMAT>|--no-position|--display-offset <N>|--panels <N>|--group-size <N>|--endianness <FORMAT>|-e|--base <B>|--terminal-width <N>|--print-color-table|--include|--completion <SHELL>>"

def err_unexpected_arg(arg_str, bin_name, tip_similar=None):
    # arg_str is like '--unknown' or '-z' or 'extra2' (for positional, no tip? Actually extra positional has no tip, different Usage? For extra positional, tip None and Usage short, no tip line.
    # For unknown long/short with similar: tip_similar is suggested long like '--color' (with --), Usage long (or short for help/version)
    # For unknown without similar: tip pass-as-value, Usage short
    # For extra positional: no tip, Usage short
    # Need to distinguish: if arg_str starts with '-' (option-like) vs positional (no dash)? For positional extra, no tip.
    if tip_similar is not None:
        # similar case
        if tip_similar in ('--help', '--version'):
            # Usage short with suggested?
            # For --helps -> --help, Usage is "{bin} --help [FILE]"
            # For --versio -> --version, Usage is "{bin} --version [FILE]"
            usage = f"{bin_name} {tip_similar} [FILE]"
        else:
            usage = f"{bin_name} {LONG_USAGE_ALL}"
        return (2, f"error: unexpected argument '{arg_str}' found\n\n  tip: a similar argument exists: '{tip_similar}'\n\nUsage: {usage}\n\nFor more information, try '--help'.\n")
    else:
        # check if positional (no dash) vs option?
        if arg_str.startswith("-"):
            # option-like without similar: pass-as-value tip, short Usage
            return (2, f"error: unexpected argument '{arg_str}' found\n\n  tip: to pass '{arg_str}' as a value, use '-- {arg_str}'\n\nUsage: {bin_name} [OPTIONS] [FILE]\n\nFor more information, try '--help'.\n")
        else:
            # positional extra: no tip, short Usage
            return (2, f"error: unexpected argument '{arg_str}' found\n\nUsage: {bin_name} [OPTIONS] [FILE]\n\nFor more information, try '--help'.\n")

def err_invalid_value(opt_display, val, possibles, bin_name, tip_val=None):
    # opt_display like '--color <WHEN>'
    # possibles like ['always','auto','never','force'] or None for terminal-width? For terminal-width, different format with cause, not possibles.
    # tip_val is suggested value like 'always' or None
    if possibles is not None:
        base = f"error: invalid value '{val}' for '{opt_display}'\n  [possible values: {', '.join(possibles)}]\n"
        if tip_val is not None:
            return (2, base + f"\n  tip: a similar value exists: '{tip_val}'\n\nFor more information, try '--help'.\n")
        else:
            return (2, base + f"\nFor more information, try '--help'.\n")
    else:
        # should not happen for invalid with possibles None? For terminal-width, use err_invalid_terminal
        return (2, f"error: invalid value '{val}' for '{opt_display}'\n\nFor more information, try '--help'.\n")

def err_invalid_terminal(val, cause, bin_name):
    return (2, f"error: invalid value '{val}' for '--terminal-width <N>': {cause}\n\nFor more information, try '--help'.\n")

def err_missing(opt_display, possibles, bin_name):
    # possibles is list or None
    if possibles is not None:
        return (2, f"error: a value is required for '{opt_display}' but none was supplied\n  [possible values: {', '.join(possibles)}]\n\nFor more information, try '--help'.\n")
    else:
        return (2, f"error: a value is required for '{opt_display}' but none was supplied\n\nFor more information, try '--help'.\n")

def err_duplicate(opt_display, bin_name):
    return (2, f"error: the argument '{opt_display}' cannot be used multiple times\n\nUsage: {bin_name} [OPTIONS] [FILE]\n\nFor more information, try '--help'.\n")

def err_conflict(first_display, second_display, first_usage, bin_name):
    # first_display like '--terminal-width <N>', second like '--panels <N>', first_usage like '--terminal-width <N>' (for Usage)
    return (2, f"error: the argument '{first_display}' cannot be used with '{second_display}'\n\nUsage: {bin_name} {first_usage} [FILE]\n\nFor more information, try '--help'.\n")

